_LOGO_PNG_BYTES = base64.b64decode(_LOGO_PNG_B64)   # decoded once at startup
_LOGO_DATA_URI  = "/logo"                            # img src → Flask /logo route


@app.route('/logo')
def serve_logo():
    """Serve logo — custom logo from DB overrides the built-in one."""
    custom_b64 = get_config('custom_logo_b64', '')
    if custom_b64:
        import base64 as _b64m
        try:
            data = _b64m.b64decode(custom_b64)
            return Response(data, mimetype='image/png',
                            headers={'Cache-Control': 'no-cache, must-revalidate'})
        except Exception:
            pass
    return Response(
        _LOGO_PNG_BYTES,
        mimetype='image/png',
        headers={'Cache-Control': 'public, max-age=3600, immutable'}
    )
