def _guarantee_effective_due(submission_date, override):
    """موعد الضمان: يدوي إن حُدد، وإلا تلقائياً قبل التقديم بـ 5 أيام."""
    if (override or "").strip():
        try:
            return datetime.strptime(override.strip()[:10], "%Y-%m-%d").date(), False
        except Exception:
            pass
    try:
        sd = datetime.strptime(str(submission_date).strip()[:10], "%Y-%m-%d").date()
        return sd - timedelta(days=5), True
    except Exception:
        return None, True

def ensure_app_config_table():
    with sqlite3.connect(str(DB_PATH)) as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS app_config (
                key        TEXT PRIMARY KEY,
                value      TEXT    DEFAULT '',
                updated_at TEXT    DEFAULT (datetime('now'))
            )
        """)
        # البذور تُقرأ من هوية الشركة -- لا أسماء مكتوبة حرفياً حتى لا تتسرب
        # هوية شركة أخرى لأي مستأجر تنقصه مفاتيح app_config.
        defaults = [
            ("company_name_ar", PROFILE.get("name_ar", "")),
            ("company_name_en", PROFILE.get("name_en", "")),
            ("system_title",    PROFILE.get("system_title", "")),
            ("system_subtitle", PROFILE.get("system_subtitle", "لوحة متابعة المنافسات")),
            ("footer_owner",    PROFILE.get("footer_owner", "")),
            ("footer_url",      PROFILE.get("footer_url", "")),
            ("custom_logo_b64", ""),
        ]
        conn.executemany(
            "INSERT OR IGNORE INTO app_config(key,value) VALUES(?,?)", defaults
        )
        conn.commit()

def get_config(key, default=""):
    try:
        with sqlite3.connect(str(DB_PATH)) as conn:
            row = conn.execute(
                "SELECT value FROM app_config WHERE key=?", (key,)
            ).fetchone()
            return row[0] if row and row[0] else default
    except Exception:
        return default

def save_config(key, value):
    with sqlite3.connect(str(DB_PATH)) as conn:
        conn.execute(
            "INSERT OR REPLACE INTO app_config(key,value,updated_at) "
            "VALUES(?,?,datetime('now'))",
            (key, value)
        )
        conn.commit()

# ══════════════════════════════════════════════════════
# AUTH
# ══════════════════════════════════════════════════════
# ── Login rate limiting: 5 failed attempts per IP → 15-minute lockout ──
_LOGIN_FAILS: dict = {}
_LOGIN_FAILS_LOCK = _threading.Lock()
_LOGIN_MAX_FAILS  = 5
_LOGIN_WINDOW_SEC = 15 * 60

def _client_ip() -> str:
    # Real visitor IP: behind Cloudflare Tunnel remote_addr is always localhost.
    return (request.headers.get("CF-Connecting-IP")
            or request.headers.get("X-Forwarded-For", "").split(",")[0].strip()
            or request.remote_addr or "unknown")

def _login_blocked(ip: str) -> bool:
    now = time.time()
    with _LOGIN_FAILS_LOCK:
        fails = [t for t in _LOGIN_FAILS.get(ip, []) if now - t < _LOGIN_WINDOW_SEC]
        if fails:
            _LOGIN_FAILS[ip] = fails
        else:
            _LOGIN_FAILS.pop(ip, None)
        return len(fails) >= _LOGIN_MAX_FAILS

def _login_failed(ip: str):
    with _LOGIN_FAILS_LOCK:
        _LOGIN_FAILS.setdefault(ip, []).append(time.time())

def _login_succeeded(ip: str):
    with _LOGIN_FAILS_LOCK:
        _LOGIN_FAILS.pop(ip, None)

_LOCKOUT_MSG = "تم إيقاف المحاولات مؤقتاً بسبب تكرار الإدخال الخاطئ — حاول مجدداً بعد 15 دقيقة"

# ── Admin password recovery: 6-digit code sent to ADMIN_USER_ID via Telegram DM ──
_RESET_CODES: dict = {}
_RESET_LOCK = _threading.Lock()
_RESET_TTL_SEC   = 10 * 60
_RESET_MAX_TRIES = 5

def _send_telegram_dm(chat_id: str, text: str) -> bool:
    if not (TELEGRAM_TOKEN and chat_id):
        return False
    try:
        r = requests.post(
            f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendMessage",
            data={"chat_id": chat_id, "text": text}, timeout=8,
        )
        return r.status_code == 200
    except Exception:
        return False

def _new_reset_code(token: str) -> str:
    code = f"{secrets.randbelow(1_000_000):06d}"
    with _RESET_LOCK:
        _RESET_CODES[token] = {"code": code, "expires": time.time() + _RESET_TTL_SEC, "tries": 0}
    return code

def _check_reset_code(token: str, code: str) -> bool:
    with _RESET_LOCK:
        entry = _RESET_CODES.get(token)
        if not entry or time.time() > entry["expires"]:
            _RESET_CODES.pop(token, None)
            return False
        entry["tries"] += 1
        if entry["tries"] > _RESET_MAX_TRIES:
            _RESET_CODES.pop(token, None)
            return False
        ok = hmac.compare_digest(code, entry["code"])
        if ok:
            _RESET_CODES.pop(token, None)
        return ok

def login_required(f):
    @functools.wraps(f)
    def wrap(*a, **kw):
        if not session.get("ok"):
            return redirect("/login")
        return f(*a, **kw)
    return wrap

@app.route("/login", methods=["GET", "POST"])
def login():
    error = ""
    if request.method == "POST":
        ip = _client_ip()
        if _login_blocked(ip):
            error = _LOCKOUT_MSG
        elif hmac.compare_digest(request.form.get("password", "").encode("utf-8"), DASH_PWD.encode("utf-8")):
            _login_succeeded(ip)
            session["ok"] = True
            return redirect("/")
        else:
            _login_failed(ip)
            error = "كلمة المرور غير صحيحة"
    return render_template_string(LOGIN_HTML, error=error, logo_uri=_LOGO_DATA_URI,
                                  expired=request.args.get("expired"),
                                  reset_ok=request.args.get("reset") == "1")

@app.route("/logout")
def logout():
    session.clear()
    return redirect("/login")

@app.route("/forgot", methods=["GET", "POST"])
def dash_forgot():
    """استعادة كلمة مرور صفحة الدخول الرئيسية -- نفس آلية /admin/forgot بالضبط،
    تُحدّث DASHBOARD_PASSWORD بدلاً من ADMIN_PASSWORD."""
    global DASH_PWD
    error = ""
    sent  = False
    token = request.form.get("token", "")
    if request.method == "POST":
        ip = _client_ip()
        action = request.form.get("action", "")
        if action == "send":
            if _login_blocked(ip):
                error = _LOCKOUT_MSG
            elif not OWNER_TELEGRAM_ID:
                error = "لم يتم ضبط OWNER_TELEGRAM_ID في .env — لا يمكن إرسال كود عبر تليجرام حتى تضبطه"
            else:
                token = secrets.token_urlsafe(16)
                code = _new_reset_code(token)
                ok = _send_telegram_dm(
                    OWNER_TELEGRAM_ID,
                    f"🔐 كود استعادة كلمة مرور الدخول: {code}\nصالح لمدة 10 دقائق. تجاهل الرسالة إن لم تطلبها.",
                )
                if ok:
                    sent = True
                else:
                    error = "تعذر إرسال الكود عبر تليجرام — تأكد من صلاحية التوكن"
        elif action == "verify":
            sent = True
            code     = request.form.get("code", "").strip()
            new_pwd  = request.form.get("new_pwd", "").strip()
            new_pwd2 = request.form.get("new_pwd2", "").strip()
            if _login_blocked(ip):
                error = _LOCKOUT_MSG
            elif not _check_reset_code(token, code):
                _login_failed(ip)
                error = "الكود غير صحيح أو منتهي الصلاحية"
            elif not new_pwd or len(new_pwd) < 8:
                error = "كلمة المرور الجديدة قصيرة (8 أحرف على الأقل)"
            elif new_pwd != new_pwd2:
                error = "كلمتا المرور غير متطابقتين"
            else:
                env_path = ENV_PATH
                try:
                    with open(env_path, "r", encoding="utf-8") as ef:
                        lines_ = ef.readlines()
                    updated = False
                    for i, line in enumerate(lines_):
                        if line.startswith("DASHBOARD_PASSWORD="):
                            lines_[i] = f"DASHBOARD_PASSWORD={new_pwd}\n"
                            updated = True
                            break
                    if not updated:
                        lines_.append(f"DASHBOARD_PASSWORD={new_pwd}\n")
                    with open(env_path, "w", encoding="utf-8") as ef:
                        ef.writelines(lines_)
                    DASH_PWD = new_pwd
                    _login_succeeded(ip)
                    return redirect("/login?reset=1")
                except Exception as ex:
                    error = f"خطأ: {ex}"
    return render_template_string(DASH_FORGOT_HTML, error=error, sent=sent,
                                   token=token, logo_uri=_LOGO_DATA_URI)

