@app.route("/admin")
@admin_required
def admin_panel():
    cfg = {}
    try:
        with sqlite3.connect(str(DB_PATH)) as conn:
            rows = conn.execute("SELECT key,value FROM app_config").fetchall()
            cfg = {r[0]: r[1] for r in rows}
    except Exception:
        pass
    stats = {}
    try:
        with sqlite3.connect(str(DB_PATH)) as conn:
            stats["tenders"]   = conn.execute(
                "SELECT COUNT(*) FROM master_tenders WHERE status='InProgress'"
            ).fetchone()[0]
            stats["engineers"] = conn.execute(
                "SELECT COUNT(*) FROM engineers WHERE is_active=1"
            ).fetchone()[0]
            stats["pending"]   = conn.execute(
                "SELECT COUNT(*) FROM pending_changes WHERE status='PENDING_APPROVAL'"
            ).fetchone()[0]
    except Exception:
        pass
    import subprocess
    try:
        r = subprocess.run(["systemctl", "is-active", "elrawaf-bot.service"],
                           capture_output=True, text=True, timeout=3)
        stats["bot"] = r.stdout.strip()
    except Exception:
        stats["bot"] = "unknown"
    return render_template_string(ADMIN_PANEL_HTML,
                                   cfg=cfg, stats=stats,
                                   version=VERSION,
                                   logo_uri=_LOGO_DATA_URI,
                                   admin_email=ADMIN_EMAIL)

