# ── بوابة المهندسين (داخل المنصة) ──────────────────────────────────────────
@app.route('/engineer-view')
@login_required
def engineer_view():
    import sqlite3 as _sq3
    from datetime import date

    with _sq3.connect(str(DB_PATH)) as conn:
        conn.row_factory = _sq3.Row

        engineers = [r[0] for r in conn.execute(
            "SELECT DISTINCT assigned_engineer FROM master_tenders "
            "WHERE assigned_engineer IS NOT NULL AND assigned_engineer != '' "
            "ORDER BY assigned_engineer"
        ).fetchall()]

        rows = conn.execute("""
            SELECT m.id, m.title, m.assigned_engineer,
                   m.submission_date, m.business_type, m.engineer_locked,
                   COALESCE(tr.did_submit, 0) as did_submit,
                   tr.result, tr.our_price, tr.winning_price
            FROM master_tenders m
            LEFT JOIN tender_results tr ON tr.tender_id = m.tender_id
            WHERE m.assigned_engineer IS NOT NULL AND m.assigned_engineer != ''
            ORDER BY
              CASE WHEN m.submission_date IS NULL OR m.submission_date='' THEN 1 ELSE 0 END,
              m.submission_date ASC
        """).fetchall()

    tenders = []
    today = date.today()
    for r in rows:
        t = dict(r)
        try:
            raw = str(t["submission_date"])[:10] if t["submission_date"] else None
            cdate = date.fromisoformat(raw) if raw else None
            t["days_left"] = (cdate - today).days if cdate else None
        except Exception:
            t["days_left"] = None
        tenders.append(t)

    total     = len(tenders)
    pending   = sum(1 for t in tenders if not t["did_submit"] and not t["result"])
    submitted = sum(1 for t in tenders if t["did_submit"] and not t["result"])
    won       = sum(1 for t in tenders if t["result"] == "won")
    lost      = sum(1 for t in tenders if t["result"] == "lost")
    eng_counts = {eng: sum(1 for t in tenders if t["assigned_engineer"] == eng)
                  for eng in engineers}

    return render_template_string(
        ENGINEER_VIEW_HTML,
        engineers=engineers,
        tenders=tenders,
        eng_counts=eng_counts,
        total_tenders=total,
        pending_tenders=pending,
        submitted_tenders=submitted,
        won_tenders=won,
        lost_tenders=lost,
    )


# ── API تحديث حالة المنافسة (للأدمن من engineer-view) ───────────────────────
@app.route('/api/admin/tender/<int:tid>/status', methods=['POST'])
@login_required
def api_admin_update_status(tid):
    """الأدمن يُحدّث حالة منافسة من بوابة المهندسين"""
    import sqlite3 as _sq3
    data   = request.get_json(silent=True) or {}
    action = data.get("action", "")
    if action not in ("submit", "no", "won", "lost"):
        return jsonify({"ok": False, "error": "إجراء غير صالح"}), 400

    with _sq3.connect(str(DB_PATH)) as conn:
        conn.row_factory = _sq3.Row
        row = conn.execute(
            "SELECT id, tender_id, title, owner, assigned_engineer FROM master_tenders WHERE id=?",
            (tid,)
        ).fetchone()
        if not row:
            return jsonify({"ok": False, "error": "غير موجودة"}), 404

        tid_str  = row["tender_id"]
        eng_name = row["assigned_engineer"] or ""
        existing = conn.execute(
            "SELECT id FROM tender_results WHERE tender_id=?", (tid_str,)
        ).fetchone()

        if action == "submit":
            if existing:
                conn.execute("UPDATE tender_results SET did_submit=1, updated_at=CURRENT_TIMESTAMP WHERE tender_id=?", (tid_str,))
            else:
                conn.execute(
                    "INSERT INTO tender_results (tender_id, title, owner, assigned_engineer, did_submit) VALUES (?,?,?,?,1)",
                    (tid_str, row["title"], row["owner"], eng_name)
                )
        elif action == "no":
            if existing:
                conn.execute("UPDATE tender_results SET did_submit=0, result=NULL, updated_at=CURRENT_TIMESTAMP WHERE tender_id=?", (tid_str,))
        elif action == "won":
            if existing:
                conn.execute("UPDATE tender_results SET did_submit=1, result='won', updated_at=CURRENT_TIMESTAMP WHERE tender_id=?", (tid_str,))
            else:
                conn.execute(
                    "INSERT INTO tender_results (tender_id, title, owner, assigned_engineer, did_submit, result) VALUES (?,?,?,?,1,'won')",
                    (tid_str, row["title"], row["owner"], eng_name)
                )
        elif action == "lost":
            if existing:
                conn.execute("UPDATE tender_results SET did_submit=1, result='lost', updated_at=CURRENT_TIMESTAMP WHERE tender_id=?", (tid_str,))
            else:
                conn.execute(
                    "INSERT INTO tender_results (tender_id, title, owner, assigned_engineer, did_submit, result) VALUES (?,?,?,?,1,'lost')",
                    (tid_str, row["title"], row["owner"], eng_name)
                )
        conn.commit()

    return jsonify({"ok": True, "action": action})

